        votingEscrow = new VotingEscrow();
    }

    function testReentrancyGuard() public {
        // attempt to call unlock function reentrantly
        (bool success, ) = address(votingEscrow).call(abi.encodeWithSelector(votingEscrow.unlock.selector));
        assertEq(success, false, "Reentrancy guard failed");
    }
}

